import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

# Rule idea: find closed regions of non-background color forming hollow boxes; fill enclosed background interior with 4.
import copy
from collections import Counter,deque
def f(g):
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[r[:] for r in g]
    # enclosed background = bg cells whose connected component touches no box boundary... simpler: flood from borders, remaining bg = enclosed
    reach=[[False]*W for _ in range(H)]
    dq=deque()
    for i in range(H):
        for j in (0,W-1):
            if not reach[i][j] and g[i][j]==bg: reach[i][j]=True; dq.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if not reach[i][j] and g[i][j]==bg: reach[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<H and 0<=nj<W and not reach[ni][nj] and g[ni][nj]==bg:
                reach[ni][nj]=True; dq.append((ni,nj))
    for i in range(H):
        for j in range(W):
            if g[i][j]==bg and not reach[i][j]: out[i][j]=4
    return out
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
res=f(G['Test input']); print(json.dumps(res))
